INSERT INTO identity.roles (key, kind, description) VALUES
  ('owner', 'staff', 'Pharmacy owner: runs the business, manages staff'),
  ('pharmacist_titular', 'staff', 'Titular pharmacist: legally responsible, manages pharmacists'),
  ('pharmacist', 'staff', 'Pharmacist: decides on pharmaceutical reviews'),
  ('pharmacy_assistant', 'staff', 'Pharmacy assistant'),
  ('customer_service', 'staff', 'Customer service'),
  ('content_editor', 'staff', 'Catalogue content editor'),
  ('customer', 'customer', 'Webshop customer'),
  ('system_bootstrap', 'system', 'Bootstrap CLI: creates the first owner'),
  ('system_auth', 'system', 'Better Auth hooks: records sign-in factor changes and requests account mails'),
  ('system_storefront', 'system', 'Storefront preview: reads active products, prices and availability (no writes)'),
  ('system_seed', 'system', 'Synthetic seed CLI: loads fake catalogue, stock, price, privacy and order data (staging and development only)'),
  ('system_maintenance', 'system', 'Worker maintenance jobs: purges personal data past its retention period'),
  ('system_reservations', 'system', 'Stock reservations: the checkout reserves, confirms, releases and consumes; the worker expires lapsed holds'),
  ('system_payments', 'system', 'Payments: the storefront''s pay route and webhook and the worker''s reconciliation record what the provider says')
